{
  "assessment": "The source packet is a single LaTeX file containing the main text and supplementary material of a Physical Review Letters paper on fractional Fermi seas in the one-dimensional Bose gas. The extraction focuses on the quantitative cluster describing the one-particle correlation function g^(1)(x) for repulsive interactions (gamma>0) across cycle branches W=0,1,2, with controls gamma and W, and readouts k_FO, nu_SD, nu_LD, and xbar. The paper reports fitted power-law exponents and crossover distances from Monte Carlo data, with error bars from five independent samplings. The source provides explicit formulas for the occupancy, entropy, and crossover distance, and describes the fitting procedure. The extraction captures the central-value relations and parameters, with uncertainty conventions preserved as source_unspecified where not defined. The case is authoring-ready with numeric controls and readouts.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Alvise Bastianello, Exotic Critical States as Fractional Fermi Seas in the One-Dimensional Bose Gas, Physical Review Letters (2026), DOI:10.1103/j3s5-gjpf",
    "journal_doi": "10.1103/j3s5-gjpf",
    "arxiv_versioned_id": "2602.17656v2"
  },
  "paper_scope": "The paper studies interaction cycles in the integrable Lieb-Liniger model, realizing fractional Fermi seas (FFS) with reduced occupancy. It uses Generalized Hydrodynamics (GHD) to predict the occupancy and computes the one-particle correlation function g^(1)(x) via Monte Carlo for repulsive interactions, extracting power-law exponents and Friedel oscillation frequencies. The extraction focuses on the quantitative cluster for gamma>0 and cycle branches W=0,1,2, as reported in Figures 2 and 3 and the supplementary material.",
  "mechanisms": [
    {
      "mechanism_id": "ghd_ffs_occupancy",
      "statement": "The GHD evolution of the occupancy under cyclic interaction changes maps the initial ground state to a fractional Fermi sea with occupancy 1/(2W+1) for |lambda| < lambda_F(gamma,W) and zero otherwise, with the running Fermi rapidity fixed by the density.",
      "equations": [
        "vartheta_{g,W}(lambda) = 1/(2W+1) if |lambda| < lambda_F(g,W), else 0",
        "1/vartheta_{g=0^+,W+1} = 2 + 1/vartheta_{g=0^-,W}"
      ],
      "variable_names": [
        "vartheta",
        "lambda",
        "lambda_F",
        "g",
        "W",
        "n"
      ],
      "parameters": [
        {
          "name": "ffs_occupancy_numerator",
          "value": 1,
          "uncertainty": "None reported",
          "unit": "dimensionless",
          "role": "Numerator in the occupancy formula",
          "anchors": [
            {
              "line_start": 180,
              "line_end": 183,
              "support": "Equation (eq_occ_FFS) states vartheta_{g,W}(lambda)=1/(2W+1) for |lambda|<lambda_F(g,W) and zero otherwise."
            }
          ]
        },
        {
          "name": "ffs_occupancy_denominator_coefficient",
          "value": 2,
          "uncertainty": "None reported",
          "unit": "dimensionless",
          "role": "Coefficient multiplying W in the denominator 2W+1",
          "anchors": [
            {
              "line_start": 180,
              "line_end": 183,
              "support": "Equation (eq_occ_FFS) shows denominator 2W+1."
            }
          ]
        },
        {
          "name": "ffs_occupancy_denominator_offset",
          "value": 1,
          "uncertainty": "None reported",
          "unit": "dimensionless",
          "role": "Constant offset in the denominator 2W+1",
          "anchors": [
            {
              "line_start": 180,
              "line_end": 183,
              "support": "Equation (eq_occ_FFS) shows denominator 2W+1."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 179,
          "line_end": 185,
          "support": "GHD predicts FFS occupancies with vartheta=1/(2W+1) for |lambda|<lambda_F, and continuity conditions at g=0."
        }
      ]
    },
    {
      "mechanism_id": "g1_powerlaw_fit",
      "statement": "The one-particle correlation function g^(1)(x) for repulsive interactions and W>=1 is fitted with an oscillating power law A cos(k_FO x + phi)/x^nu, with a short-distance exponent nu_SD and a long-distance exponent nu_LD, and a crossover distance xbar defined by the intersection of the two power-law envelopes.",
      "equations": [
        "g^(1)(x) = A cos(k_FO x + phi) / x^nu",
        "xbar = exp[(log A_SD - log A_LD)/(nu_LD - nu_SD)]"
      ],
      "variable_names": [
        "g^(1)",
        "x",
        "A",
        "k_FO",
        "phi",
        "nu",
        "nu_SD",
        "nu_LD",
        "xbar"
      ],
      "parameters": [
        {
          "name": "g1_fit_amplitude",
          "value": 1,
          "uncertainty": "Not reported as a single value; amplitudes A_SD and A_LD are fit parameters.",
          "unit": "dimensionless",
          "role": "Amplitude in the oscillating power-law fit",
          "anchors": [
            {
              "line_start": 206,
              "line_end": 206,
              "support": "Fit function A cos(k_FO x+phi)/x^nu."
            }
          ]
        },
        {
          "name": "g1_fit_phase",
          "value": 0,
          "uncertainty": "Not reported as a single value; phase phi is a fit parameter.",
          "unit": "rad",
          "role": "Phase in the oscillating power-law fit",
          "anchors": [
            {
              "line_start": 206,
              "line_end": 206,
              "support": "Fit function A cos(k_FO x+phi)/x^nu."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 206,
          "line_end": 207,
          "support": "Fit with A cos(k_FO x+phi)/x^nu, with nu_SD and nu_LD, and crossover distance xbar defined by equality of envelopes."
        },
        {
          "line_start": 467,
          "line_end": 470,
          "support": "xbar defined as exp[(log A_SD - log A_LD)/(nu_LD - nu_SD)]."
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "homogeneous_system",
      "statement": "The system is homogeneous (no trapping potential), as considered in the main text.",
      "anchors": [
        {
          "line_start": 157,
          "line_end": 157,
          "support": "We consider homogeneous systems starting from the ground state."
        }
      ]
    },
    {
      "condition_id": "no_bound_states_forward",
      "statement": "In the forward cycle, no bound states are generated; only real rapidities are considered.",
      "anchors": [
