          "line_start": 159,
          "line_end": 160,
          "support": "When the cycle is traversed in the forward direction no bound states are generated."
        }
      ]
    },
    {
      "condition_id": "density_one",
      "statement": "The particle density is n=1 (with N=30 particles and L=30).",
