          "support": "We consider N=30 particles and L=30, in such a way the density is one n=1."
        }
      ]
    },
    {
      "condition_id": "monte_carlo_parameters",
      "statement": "Monte Carlo sampling uses N=30, L=30, 2e6 updates of mu-configurations sampled every 2e4 steps, lambda-configurations sampled every 5e5 steps, delta_max=4, and 5 independent realizations of about 1000 samples each.",
      "anchors": [
        {
          "line_start": 440,
          "line_end": 442,
          "support": "Details of Monte Carlo parameters: N=30, L=30, 2e6 updates, sampling intervals, delta_max=4, 5 independent realizations."
        }
      ]
    }
  ],
  "controls": [
    {
      "name": "gamma",
      "definition": "Normalized interaction strength gamma = 2m g / (hbar^2 n), where g is the 1D coupling.",
      "unit": "dimensionless",
      "domain_kind": "numeric_values",
      "minimum": null,
      "maximum": null,
      "allowed_values": [
        1,
        5,
        20,
