      ],
      "domain_statement": "The paper reports data for gamma values including 1, 5, 20, and 25, as shown in figures and supplementary material.",
      "anchors": [
        {
          "line_start": 168,
          "line_end": 170,
          "support": "Figure 2 caption mentions gamma=25 as an example; Figure S1 shows gamma=5; Figure S2 shows gamma=1 and gamma=20."
        }
      ]
    },
    {
      "name": "W",
