  ],
  "readouts": [
    {
      "name": "k_FO",
      "definition": "Friedel oscillation wavevector, the frequency of oscillations in g^(1)(x), extracted from the fit A cos(k_FO x + phi)/x^nu.",
      "unit": "inverse length (units of n)",
      "statistic": "Fit parameter from the oscillating power-law fit to Monte Carlo data; error bars from comparing fits of five independent Monte Carlo samplings.",
      "uncertainty": "Error bars obtained by comparing fits of five independent Monte Carlo samplings; omitted when negligible on plot scale.",
      "resolution": null,
