          "support": "Figure 3(a) shows FO frequency; error bars from five independent samplings."
        }
      ]
    },
    {
      "name": "nu_SD",
      "definition": "Short-distance power-law exponent of the oscillating decay in g^(1)(x), extracted from fitting the short-distance interval.",
      "unit": "dimensionless",
      "statistic": "Fit parameter from the oscillating power-law fit; error bars from comparing fits of five independent Monte Carlo samplings.",
      "uncertainty": "Error bars obtained by comparing fits of five independent Monte Carlo samplings; shown only for LD exponent in Figure 3(b).",
      "resolution": null,
      "anchors": [
        {
          "line_start": 206,
          "line_end": 206,
          "support": "Identify transition between short-distance exponent nu_SD and long-distance exponent nu_LD."
        },
        {
          "line_start": 196,
          "line_end": 197,
          "support": "Figure 3(b) reports SD and LD power law exponents."
        }
      ]
    },
    {
      "name": "nu_LD",
      "definition": "Long-distance power-law exponent of the oscillating decay in g^(1)(x), extracted from fitting the long-distance interval.",
      "unit": "dimensionless",
      "statistic": "Fit parameter from the oscillating power-law fit; error bars from comparing fits of five independent Monte Carlo samplings.",
      "uncertainty": "Error bars obtained by comparing fits of five independent Monte Carlo samplings; shown for LD exponent in Figure 3(b).",
      "resolution": null,
      "anchors": [
