      ]
    },
    {
      "name": "xbar",
      "definition": "Crossover distance between the short-distance and long-distance power laws, defined as the intersection of the two power-law envelopes.",
      "unit": "inverse density units (since n=1)",
      "statistic": "Computed from fitted amplitudes and exponents via xbar = exp[(log A_SD - log A_LD)/(nu_LD - nu_SD)]; error bars from comparing fits of five independent Monte Carlo samplings.",
      "uncertainty": "Error bars obtained by comparing fits of five independent Monte Carlo samplings; shown for xbar in Figure 3(a).",
      "resolution": null,
      "anchors": [
        {
          "line_start": 207,
          "line_end": 207,
          "support": "Crossover distance xbar defined as distance where short-distance and large-distance envelopes are equal."
        },
        {
          "line_start": 467,
          "line_end": 470,
          "support": "xbar = exp[(log A_SD - log A_LD)/(nu_LD - nu_SD)]."
        }
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "ffs_occupancy_claim",
      "statement": "After W cycles, the occupancy of the GGE is reduced to 1/(2W+1) for rapidities within the Fermi sea, and zero otherwise.",
      "quantitative_form": "vartheta_{g,W}(lambda) = 1/(2W+1) for |lambda| < lambda_F(g,W), else 0",
      "oracle_outputs": {
