    {
      "claim_id": "g1_powerlaw_claim",
      "statement": "For repulsive interactions and W>=1, the one-particle correlation function g^(1)(x) exhibits an oscillating power-law decay with a short-distance exponent nu_SD and a long-distance exponent nu_LD, with a crossover distance xbar.",
      "quantitative_form": "g^(1)(x) = A cos(k_FO x + phi)/x^nu, with nu=nu_SD for x<xbar and nu=nu_LD for x>xbar",
      "oracle_outputs": {
